import re
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()



def od_order_number(message_ref: str) -> str:
    import hashlib

    return "OD-" + hashlib.sha1(message_ref.encode("utf-8")).hexdigest()[:8].upper()


file_path = od_text(params.get("file_path"))
file_name = od_text(params.get("file_name")) or file_path.split("/")[-1]
sender = od_text(params.get("sender"))
subject = od_text(params.get("subject")) or file_name
source_text = od_text(params.get("source_text"))
if not file_path:
    raise ValueError("file_path is required: the path of the order file in the agent's files, for example Orders/po-1042.pdf")
fingerprint = od_text(params.get("fingerprint"))
message_ref = "file:" + (fingerprint or file_path)
order_number = od_order_number(message_ref)
existing = [r for r in od_rows("od_orders", order_number) if od_text(r.get("title")) == order_number]
already = bool(existing)
if existing:
    order_id = od_text(existing[0].get("id"))
else:
    header = [x for x in ["From: " + sender if sender else "", "Subject: " + subject if subject else "", "File: " + file_path] if x]
    text = ("\n".join(header) + "\n\n" + source_text).strip()
    if len(text) > 60000:
        text = text[:60000] + "\n[The rest of this order was too long to keep here. Open the original file.]"
    data: dict[str, Any] = {"message_ref": message_ref[:300], "received_on": od_now(), "source_text": text, "source_file": file_path[:500]}
    order = api.records.create(type_slug="od_orders", record={"title": order_number, "data": data})
    order_id = od_text(order.get("id"))
